import { getToken } from "./token.js"
import { div, h1, ul, li, a, span, button, p, input, h4, select, option, label, table, thead, tbody, tr, th, td } from "./dsl.js";

const API_BASE_URL = "http://localhost:8080"

function getHome(mainContent){
    const view = div({},
        h1({}, "Welcome to Houses & Bookings"),
    );
    const existing = document.getElementById("housesList");
    if (existing) existing.remove();

    const listButton =
        a({ href: `#houses`, class: "btn btn-sm btn-info" }, "Get All Houses")
    const createLocationButton =
        a({ href: `#locations/create`, class: "btn btn-sm btn-primary ms-2" }, "Create New Location")

    view.appendChild(listButton);
    view.appendChild(createLocationButton);

    mainContent.replaceChildren(view);
}

function getLocationDetails(mainContent, params){
    const id = params.id

    fetch(API_BASE_URL + "/locations/" + id)
        .then(res => {
            if (!res.ok) throw new Error(`Failed to fetch location details (status: ${res.status})`)
            return res.json()
        })
        .then(location => {
            const parentPromise = location.parentId
                ? fetch(API_BASE_URL + "/locations/" + location.parentId).then(r => r.json())
                : Promise.resolve(null)

            parentPromise.then(parent => {
                const view = div({},
                    h1({}, "Location Details"),
                    ul({ class: "list-group mt-3" },
                        createListItem("Name", location.name),
                        createListItem("Type", location.type),
                        createListItem("Parent", parent ? parent.name : "None")
                    ),
                    a({ href: "#locations/create", class: "btn btn-primary mt-3" }, "Create New Location")
                )
                mainContent.replaceChildren(view)
            })
        })
        .catch(err => showError(mainContent, err))
}

function getUserDetails(mainContent, params){
    const id = params.id

    fetch(API_BASE_URL + "/users/" + id, {
        headers: {
            "Authorization": "Bearer " + getToken()
        }
    })
        .then(res => {
            if (!res.ok) throw new Error(`Failed to fetch user details (status: ${res.status})`)
            return res.json()
        })
        .then(user => {
            const view = div({},
                h1({}, "User Details"),
                ul({ class: "list-group mt-3" },
                    createListItem("ID", user.id),
                    createListItem("Username", user.name),
                    createListItem("Email", user.email)
                ),
                a({ href: `#users/${id}/bookings`, class: "btn btn-primary mt-4" }, "View My Bookings")
            );

            mainContent.replaceChildren(view);
        })
        .catch(err => showError(mainContent, err));
}

function getBookings(mainContent, params) {
    const hid = params.hid;
    const skip = params?.skip ? parseInt(params.skip) : 0
    const limit = params?.limit ? parseInt(params.limit) : 2

    fetch(`${API_BASE_URL}/bookings?hid=${hid}&skip=${skip}&limit=${limit}`, {
        headers: {
            "Authorization": "Bearer " + getToken()
        }
    })
        .then(res => {
            if (!res.ok) throw new Error(`Failed to fetch bookings (status: ${res.status})`);
            return res.json();
        })
        .then(bookings => {
            const bookingItems = bookings.length === 0
                ? [li({ class: "list-group-item text-warning" }, "No bookings found for this house.")]
                : bookings.map(booking =>
                    li({ class: "list-group-item d-flex justify-content-between align-items-center" },
                        span({}, `Booking #${booking.id} | ${booking.startDate} → ${booking.endDate}`),
                        a({ href: `#bookings/${booking.id}`, class: "btn btn-sm btn-info" }, "Details")
                    )
                );

            const prevBtn = skip > 0
                ? a({ href: `#houses/${hid}/bookings?skip=${skip - limit}&limit=${limit}`, class: "btn btn-outline-secondary me-2" }, "← Previous")
                : null

            const nextBtn = bookings.length === limit
                ? a({ href: `#houses/${hid}/bookings?skip=${skip + limit}&limit=${limit}`, class: "btn btn-outline-secondary" }, "Next →")
                : null

            const pagination = div({ class: "d-flex mt-3" },
                ...[prevBtn, nextBtn].filter(Boolean)
            )

            const view = div({},
                h1({}, "Bookings for House " + hid),
                ul({ class: "list-group mt-3" }, ...bookingItems),
                pagination
            );

            mainContent.replaceChildren(view);
        })
        .catch(err => showError(mainContent, err));
}

function getBookingDetails(mainContent, params) {
    const id = params.id;

    fetch(API_BASE_URL + "/bookings/" + id, {
        headers: { "Authorization": "Bearer " + getToken() }
    })
        .then(res => {
            if (!res.ok) throw new Error(`Failed to fetch booking details (status: ${res.status})`);
            return res.json();
        })
        .then(booking => {
            const view = div({},
                h1({}, "Booking details #" + booking.id),

                ul({ class: "list-group mt-3 mb-4" },
                    li({ class: "list-group-item" }, "House: ", a({ href: `#houses/${booking.houseId}`}, `House ${booking.houseId}`)),
                    li({ class: "list-group-item" }, `Start Date: ${booking.startDate}`),
                    li({ class: "list-group-item" }, `End Date: ${booking.endDate}`),
                    li({ class: "list-group-item" }, "Booker: ", a({ href: `#users/${booking.userId}` }, `User ${booking.userId}`))
                ),

                //delete booking
                button({
                    class: "btn btn-danger mb-5",
                    onclick: () => {
                        if (confirm("Are you sure you want to delete this booking?")) {
                            fetch(API_BASE_URL + "/bookings/" + id, {
                                method: "DELETE",
                                headers: { "Authorization": "Bearer " + getToken() }
                            })
                                .then(res => {
                                    if (res.status === 204) {
                                        alert("Booking deleted");
                                        window.location.hash = "#home";
                                    } else throw new Error("Failed to delete booking");
                                })
                                .catch(err => showError(mainContent, err));
                        }
                    }
                }, "Delete Booking"),

                //update booking
                h4({}, "Change Dates"),
                input({ id: "newStart", type: "date", class: "form-control mb-2", value: booking.startDate }),
                input({ id: "newEnd", type: "date", class: "form-control mb-3", value: booking.endDate }),
                button({
                    class: "btn btn-success",
                    onclick: () => {
                        const start = document.getElementById("newStart").value;
                        const end = document.getElementById("newEnd").value;

                        if (start === booking.startDate && end === booking.endDate) {
                            alert("No changes detected in dates.");
                            return;
                        }

                        fetch(API_BASE_URL + "/bookings/" + id, {
                            method: "PUT",
                            headers: {
                                "Authorization": "Bearer " + getToken(),
                                "Content-Type": "application/json"
                            },
                            body: JSON.stringify({ startDate: start, endDate: end })
                        })
                            .then(res => {
                                if (res.ok) {
                                    alert("Booking updated successfully!");
                                    getBookingDetails(mainContent, params);
                                } else if (res.status === 400 || res.status === 409) {
                                    alert("Those dates are invalid or overlap with another booking!");
                                } else {
                                    throw new Error("Failed to update booking");
                                }
                            })
                            .catch(err => showError(mainContent, err));
                    }
                }, "Update Booking")
            );

            mainContent.replaceChildren(view);
        })
        .catch(err => showError(mainContent, err));
}

function getUserBookings(mainContent, params) {
    const id = params.id
    const skip = params?.skip ? parseInt(params.skip) : 0
    const limit = params?.limit ? parseInt(params.limit) : 2

