                );

            const prevBtn = skip > 0
                ? a({ href: `#users/${id}/bookings?skip=${skip - limit}&limit=${limit}`, class: "btn btn-outline-secondary me-2" }, "← Previous")
                : null

            const nextBtn = bookings.length === limit
                ? a({ href: `#users/${id}/bookings?skip=${skip + limit}&limit=${limit}`, class: "btn btn-outline-secondary" }, "Next →")
                : null

            const pagination = div({ class: "d-flex mt-3" },
                ...[prevBtn, nextBtn].filter(Boolean)
            )

            const view = div({},
                h1({}, "Bookings for User " + id),
                ul({ class: "list-group mt-3 mb-4" }, ...bookingItems),
                pagination
            );

            mainContent.replaceChildren(view);
        })
        .catch(err => showError(mainContent, err))
}

function getHouses(mainContent, params) {
    const skip = params?.skip ? parseInt(params.skip) : 0
    const limit = params?.limit ? parseInt(params.limit) : 2


    fetch(`${API_BASE_URL}/houses?skip=${skip}&limit=${limit}`, {
        headers: {
            "Authorization": "Bearer " + getToken()
        }
    })
        .then(res => {
            if (!res.ok) throw new Error(`Failed to fetch houses (status: ${res.status})`);
