            const prevBtn = skip > 0
                ? a({ href: `#houses?skip=${skip - limit}&limit=${limit}`, class: "btn btn-outline-secondary me-2" }, "← Previous")
                : null

            const nextBtn = data.houses.length === limit
                ? a({ href: `#houses?skip=${skip + limit}&limit=${limit}`, class: "btn btn-outline-secondary" }, "Next →")
                : null

            const pagination = div({ class: "d-flex mt-3" },
                ...[prevBtn, nextBtn].filter(Boolean)
            )

            const view = div({},
                h1({}, "Houses"),
                ul({ class: "list-group mt-3" }, ...listItems),
                pagination
            )

            mainContent.replaceChildren(view);
        })
        .catch(err => showError(mainContent, err));
}

function getHouseDetails(mainContent, params) {
    const id = params.id;

    fetch(API_BASE_URL + "/houses/" + id, {
        headers: {
            "Authorization": "Bearer " + getToken()
        }
    })
        .then(res => {
            if (!res.ok) throw new Error(`Failed to fetch booking details (status: ${res.status})`);
            return res.json();
        })
        .then(house => {
            const view = div({},
                h1({}, `House #${house.id} details`),
                ul({ class: "list-group mt-3 mb-4" },
