                        "Bookings: ",
                        a({ href: `#houses/${house.id}/bookings` }, `${house.title}'s bookings`)
                    )
                )
            );

            mainContent.replaceChildren(view);
        })
        .catch(err => showError(mainContent, err));
}


function createLocationView(mainContent) {
    const parentTypeMap = {
            'REGION': 'COUNTRY',
            'CITY': 'REGION',
            'MUNICIPALITY': 'CITY',
            'LOCALITY': 'MUNICIPALITY'
        }

    const nameInput = input({
        id: 'locationName',
        type: 'text',
        class: 'form-control mb-3',
        placeholder: 'Location name'
    })

    const typeSelect = select({ id: 'locationType', class: 'form-select mb-3' },
        option({ value: '' }, '-- Select type --'),
        ...['COUNTRY', 'REGION', 'CITY', 'MUNICIPALITY', 'LOCALITY']
            .map(t => option({ value: t }, t))
    )

    const parentContainer = div({ id: 'parentContainer', class: 'mb-3' })
    const existingContainer = div({ id: 'existingContainer', class: 'mt-4' })

    typeSelect.addEventListener('change', () => {
        const selectedType = typeSelect.value
        parentContainer.replaceChildren()
        existingContainer.replaceChildren()

        if (!selectedType) return
        if (selectedType === 'COUNTRY') {
            fetch(`${API_BASE_URL}/locations?type=COUNTRY`)
                .then(res => res.json())
                .then(countries => {
                    if (typeSelect.value !== selectedType) return
                    existingContainer.appendChild(h4({}, 'Existing COUNTRYs'))
                    if (countries.length === 0) {
                        existingContainer.appendChild(p({ class: 'text-muted' }, 'No countries created yet.'))
                        return
                    }
                    existingContainer.appendChild(
                        table({ class: 'table table-bordered table-sm' },
                            thead({}, tr({}, th({}, 'Name'))),
                            tbody({}, ...countries.map(loc => tr({}, td({}, loc.name))))
                        )
                    )
                })
                .catch(err => showError(mainContent, err))
            return
        }

        const parentType = parentTypeMap[selectedType]

        Promise.all([
                fetch(`${API_BASE_URL}/locations?type=${parentType}`).then(r => r.json()),
                fetch(`${API_BASE_URL}/locations?type=${selectedType}`).then(r => r.json())
            ]).then(([parentLocations, existingLocations]) => {
                if (typeSelect.value !== selectedType) return

                // Parent picker
                if (parentLocations.length === 0) {
                    parentContainer.appendChild(
                        p({ class: 'text-warning' }, `No ${parentType} available. Create one first.`)
                    )
                } else {
                    parentContainer.appendChild(label({ class: 'form-label' }, `Parent ${parentType}`))
                    parentContainer.appendChild(
                        select({ id: 'parentId', class: 'form-select' },
                            option({ value: '' }, `-- Select ${parentType} --`),
                            ...parentLocations.map(loc => option({ value: String(loc.id) }, loc.name))
                        )
                    )
                }

                // Existing locations table with parent name lookup
                const parentMap = Object.fromEntries(parentLocations.map(l => [String(l.id), l.name]))

                existingContainer.appendChild(h4({}, `Existing ${selectedType}s`))
                if (existingLocations.length === 0) {
                    existingContainer.appendChild(p({ class: 'text-muted' }, `No ${selectedType} locations created yet.`))
                    return
                }
                existingContainer.appendChild(
                    table({ class: 'table table-bordered table-sm' },
                        thead({}, tr({}, th({}, 'Name'), th({}, parentType))),
                        tbody({},
                            ...existingLocations.map(loc =>
                                tr({},
                                    td({}, loc.name),
                                    td({}, parentMap[String(loc.parentId)] || '-')
                                )
                            )
                        )
                    )
                )
            }).catch(err => showError(mainContent, err))
    })

    const form = document.createElement('form')
    form.appendChild(label({ class: 'form-label' }, 'Name'))
    form.appendChild(nameInput)
    form.appendChild(label({ class: 'form-label' }, 'Type'))
    form.appendChild(typeSelect)
    form.appendChild(parentContainer)
    form.appendChild(button({ type: 'submit', class: 'btn btn-primary mt-3' }, 'Create Location'))
    form.appendChild(existingContainer)

    form.addEventListener('submit', e => {
        e.preventDefault()

        const name = document.getElementById('locationName').value.trim()
        const type = document.getElementById('locationType').value

        if (!name) { alert('Name is required'); return }
        if (!type) { alert('Type is required'); return }

        const parentSelect = document.getElementById('parentId')
        const parentId = parentSelect ? parseInt(parentSelect.value) || null : null

        if (type !== 'COUNTRY' && !parentId) {
            alert('Please select a parent location')
            return
        }

        const body = parentId ? { name, type, parentId } : { name, type }

        fetch(`${API_BASE_URL}/locations`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': 'Bearer ' + getToken()
            },
            body: JSON.stringify(body)
        })
            .then(res => {
                if (res.status === 201) return res.json()
                return res.text().then(msg => { throw new Error(msg) })
            })
            .then(data => {
                window.location.hash = `locations/${data.locationId}`
            })
            .catch(err => showError(mainContent, err))
    })

    mainContent.replaceChildren(div({}, h1({}, 'Create Location'), form))
}

// Helper functions

function createListItem(label, value) {
    return li({ class: "list-group-item" }, `${label}: ${value}`);
}

function showError(container, error) {
    container.appendChild(p({ class: "text-danger mt-3" }, "Error: " + error.message));
}

export const handlers = {
    getHome,
    getLocationDetails,
    getUserDetails,
    getBookings,
    getBookingDetails,
    getUserBookings,
    getHouseDetails,
    getHouses,
    createLocationView
}

export default handlers

import { getToken } from "./token.js"
import { div, h1, ul, li, a, span, button, p, input, h4, select, option, label, table, thead, tbody, tr, th, td } from "./dsl.js";

