                                    } else {
                                        throw new Error("Failed to update booking");
                                    }
                                })
                                .catch(err => showError(mainContent, err));
                        }
                    }, "Update Booking")
                );

                mainContent.replaceChildren(view);
            }).catch(err => showError(mainContent, err));
        })
        .catch(err => showError(mainContent, err));
}

function getUserBookings(mainContent, params) {
    const id = params.id
    const skip = params?.skip ? parseInt(params.skip) : 0
    const limit = params?.limit ? parseInt(params.limit) : 2

    fetch(`${API_BASE_URL}/users/${id}/bookings?skip=${skip}&limit=${limit}`, {
        headers: {
            "Authorization": "Bearer " + getToken()
        }
    })
        .then(res => {
            if (!res.ok) throw new Error(`Failed to fetch user bookings (status: ${res.status})`)
            return res.json()
        })
        .then(bookings => {
            const bookingItems = bookings.length === 0
                ? [li({ class: "list-group-item" }, "No bookings found for this user.")]
                : bookings.map(booking =>
                    li({ class: "list-group-item d-flex justify-content-between align-items-center" },
                        span({}, `Booking #${booking.id} — House ${booking.houseId} | ${booking.startDate} → ${booking.endDate}`),
                        a({ href: `#bookings/${booking.id}`, class: "btn btn-sm btn-info" }, "Details")
                    )
                );

            const prevBtn = skip > 0
                ? a({ href: `#users/${id}/bookings?skip=${skip - limit}&limit=${limit}`, class: "btn btn-outline-secondary me-2" }, "← Previous")
                : null

            const nextBtn = bookings.length === limit
                ? a({ href: `#users/${id}/bookings?skip=${skip + limit}&limit=${limit}`, class: "btn btn-outline-secondary" }, "Next →")
                : null

            const pagination = div({ class: "d-flex mt-3" },
                ...[prevBtn, nextBtn].filter(Boolean)
            )

            const view = div({},
                h1({}, "Bookings for User " + id),
                ul({ class: "list-group mt-3 mb-4" }, ...bookingItems),
                pagination
            );

            mainContent.replaceChildren(view);
        })
        .catch(err => showError(mainContent, err))
}

function getHouses(mainContent, params) {
    const skip = params?.skip ? parseInt(params.skip) : 0
    const limit = params?.limit ? parseInt(params.limit) : 2


    fetch(`${API_BASE_URL}/houses?skip=${skip}&limit=${limit}`, {
